  "v2.reprisal.lost": "{muscle|cap} se dresse au-dessus de vous : {fine} pièces pour {name}.",
  "v2.reprisal.lostBack": "{muscle|cap} se dresse au-dessus de vous : elle reprend {items} pour {name}, et {fine} pièces pour sa peine.",
  "v2.reprisal.none": "Personne ne vous attend.",
  "v2.reprisal.notSport": "{name|cap} est là pour une dette, pas pour le plaisir.",
  "v2.reprisal.off": "Vous vous écartez du sable. {name|cap} vous attendra sur le quai.",
  "v2.reprisal.enter": "Entrer sur le sable pour affronter {name}",
  "v2.line.aldric": "« Une sangle, et les qualifications étaient finies pour moi. Je m’entraîne encore : un combat sur le sable, si vous avez la mise. »",
  "v2.line.aldric.hauberk": "« C’est mon haubert que vous portez. Mère a bien choisi. Un combat sur le sable, si vous avez la mise ? »",
  "v2.line.corra": "« Un bâton à louer, une pièce le coup. Ou un combat sur le sable, si tu as la mise. »",
  "v2.line.corra.reprisal": "« {name|cap} m’envoie : tu as pris ce qui lui appartenait. Paie-moi {n} pièces, ou retrouve-moi sur le sable. »",
  "v2.line.ambrose": "« J’ai perdu la bourse du sanctuaire aux qualifications. Un combat amical paie l’huile des lampes, si vous avez la mise. »",
  "v2.line.lucan": "« Marek m’a sorti des qualifications en quatre coups. Je m’entraîne chaque soir jusqu’à ce qu’il lui en faille cinq. Un combat sur le sable, si vous avez la mise. »",
  "v2.line.piers": "« Les marchands du fleuve me paient pour garder leurs barges jusqu’à ce que la couronne soit gagnée. Un combat sur le sable garde la lance éveillée, si vous avez la mise. »",
  "v2.line.kell": "« Ni lame ni armure : ces deux poings, c’est tout ce que j’ai apporté. Quelques pièces sur le sable, si tu as la mise. »",
  "v2.line.tobin.in": "« Souhaite-moi bonne chance : je suis toujours en course ! »",
  "v2.line.tobin.out": "« Hors course pour la couronne. Mais je peux encore battre quelqu’un, pas vrai ? Un combat ? »",
  "v2.line.rhosk.in": "« La couronne d’abord. On parlera après. »",
  "v2.line.rhosk.out": "« Pas de couronne, pas de contrat, alors. Un combat pour quelques pièces fera l’affaire. »",
